import{_ as a,o,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Applicazioni","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/applicazioni.md","filePath":"user-guide/applicazioni.md"}'),t={name:"user-guide/applicazioni.md"};function l(r,e,s,c,d,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="applicazioni" tabindex="-1">Applicazioni <a class="header-anchor" href="#applicazioni" aria-label="Permalink to &quot;Applicazioni&quot;">​</a></h1><p>Un&#39;<strong>applicazione</strong> è una pagina web registrata nel vault, per esempio uno strumento che usate ogni giorno (una chat, un calendario, una dashboard, un servizio interno). Si apre in una scheda, accanto alle vostre note, senza uscire da Clarae notanda.</p><blockquote><p><strong>La funzione è accesa di default.</strong> Chi amministra il cloud può spegnerla, con il flag <code>features.web_viewer</code> nel vostro profilo di configurazione: se nel ribbon, nel pannello vuoto e nell&#39;esploratore dei file non c&#39;è <em>Nuova applicazione</em>, è spenta per voi. Senza un cloud (un vault solo locale) non c&#39;è un profilo e la funzione resta accesa. Fino alla 1.7.1 era spenta di default. Il responsabile del progetto l&#39;ha provata su finestre vere di Windows e di Linux il 27 novembre 2026, con esito positivo: vedi <a href="#limiti">Limiti</a>.</p></blockquote><h2 id="dove-funziona" tabindex="-1">Dove funziona <a class="header-anchor" href="#dove-funziona" aria-label="Permalink to &quot;Dove funziona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dove</th><th>Che cosa succede</th></tr></thead><tbody><tr><td><strong>Client desktop su macOS</strong></td><td>La pagina si apre <strong>dentro la scheda</strong>, in un browser incorporato (quello del sistema, WebKit).</td></tr><tr><td><strong>Client desktop su Windows</strong></td><td>Come su macOS, con <strong>WebView2</strong> (il motore di Microsoft Edge). Serve il <em>WebView2 Runtime</em> dalla versione <strong>1.0.2210.55</strong>; senza, o con uno più vecchio, vale il ripiego descritto sotto.</td></tr><tr><td><strong>Client desktop su Linux</strong></td><td>Come su macOS, con <strong>WebKitGTK</strong>. Serve <code>webkit2gtk-4.1</code> dalla versione <strong>2.40</strong>, il pacchetto ufficiale (costruito per GTK 3) e <strong>bubblewrap (<code>bwrap</code>)</strong> installato e funzionante: WebKit mette la pagina in una sandbox e l&#39;app non la apre senza. Senza questi requisiti, o in un ambiente che non permette la sandbox (un container, un sistema con i namespace utente spenti, Flatpak o Snap), vale il ripiego descritto sotto.</td></tr><tr><td><strong>Workbench web</strong></td><td>La pagina non può stare dentro un&#39;altra pagina web (molti siti lo vietano): la scheda mostra il riquadro con <strong>«Apri nel browser»</strong>, che apre una nuova scheda del browser.</td></tr></tbody></table><p><strong>Il ripiego.</strong> Se il computer non può mostrare la pagina nella scheda (manca il runtime o è troppo vecchio, su Linux manca <code>bwrap</code> o la sandbox non si può creare, la finestra non ha la struttura che il driver si aspetta, oppure la vista integrata è stata spenta), la scheda mostra il riquadro con il pulsante <strong>«Apri nel browser»</strong>, che apre la pagina nel browser predefinito del sistema. Non compaiono errori: se la prima apertura trova il sistema incapace, per il resto della sessione le applicazioni mostrano direttamente il riquadro.</p><p><strong>Spegnere la vista integrata su un computer.</strong> Su Windows e su Linux si può avviare l&#39;app con la variabile d&#39;ambiente <code>CLARAE_WEBVIEW=off</code> (vale solo il valore <code>off</code>): le applicazioni si aprono allora nel browser di sistema. Serve a chi ha un computer dove la vista si comporta male. Su macOS la variabile non esiste.</p><p>Nei casi senza browser incorporato (workbench web, o ripiego) tutto il resto della guida vale ugualmente (creare, rinominare, cambiare indirizzo, aprire dal browser), tranne le sezioni che parlano della barra, delle scorciatoie e dei dati di sessione.</p><h2 id="creare-un-applicazione" tabindex="-1">Creare un&#39;applicazione <a class="header-anchor" href="#creare-un-applicazione" aria-label="Permalink to &quot;Creare un&#39;applicazione&quot;">​</a></h2><p><em>Nuova applicazione</em> dall&#39;<strong>esploratore dei file</strong> (il pulsante nella sua barra, o la voce del menu che si apre con il tasto destro su una cartella, su un file o sullo spazio vuoto), dal ribbon, dal pannello vuoto o dalla palette comandi (<code>Mod+P</code>). Dall&#39;esploratore il file nasce <strong>nella cartella della riga selezionata</strong> (o accanto al file selezionato; in cima al vault se non c&#39;è una selezione). Il dialogo chiede:</p><ul><li><strong>Indirizzo:</strong> un indirizzo <code>http</code> o <code>https</code>, per esempio <code>https://example.com</code>. Se scrivete <code>example.com</code> o <code>localhost:3000</code> senza schema, aggiunge <code>https://</code>. Non sono accettati altri schemi (<code>file:</code>, <code>javascript:</code>, <code>mailto:</code>…), indirizzi con nome utente e password, spazi o caratteri di controllo.</li><li><strong>Nome</strong> (facoltativo): il nome del file. Se manca, quello del sito (senza <code>www.</code>).</li></ul><p>Il comando scrive un file <code>Nome.webapp</code> (dal ribbon, dal pannello vuoto e dalla palette: accanto al file attivo; dall&#39;esploratore: nella cartella scelta) e lo apre in una nuova scheda. L&#39;esploratore e le schede mostrano il <strong>nome senza <code>.webapp</code></strong>: <code>Mio sito.webapp</code> compare come «Mio sito». Su un vault in sola lettura <em>Nuova applicazione</em> e <em>Cambia indirizzo</em> sono disabilitati.</p><p>Il file è un piccolo JSON, che potete anche scrivere a mano:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Un <code>.webapp</code> è <strong>un file come gli altri</strong>: si rinomina, si sposta, si elimina, si segnala con i segnalibri e <strong>si sincronizza</strong> con il vault. Se due dispositivi lo cambiano insieme vale l&#39;ultima scrittura (stesso utente) oppure nasce una copia di conflitto (utenti diversi, come per ogni file che non è una nota).</p><h2 id="aprire-un-applicazione" tabindex="-1">Aprire un&#39;applicazione <a class="header-anchor" href="#aprire-un-applicazione" aria-label="Permalink to &quot;Aprire un&#39;applicazione&quot;">​</a></h2><ul><li>Dall&#39;esploratore dei file, con un clic sul file <code>.webapp</code>.</li><li>Dal <strong>selettore rapido</strong> (<code>Mod+O</code>): digitate parte del nome dell&#39;applicazione; la trova insieme alle note, alle lavagne, alle basi e ai disegni (dalla 1.7.1). Il tipo è scritto accanto al nome e letto dai lettori di schermo.</li><li>Dalla palette: <strong><em>Apri applicazione…</em></strong> elenca le sole applicazioni del vault.</li><li>Un <code>.webapp</code> incorporato in una nota (<code>![[Nome.webapp]]</code>) non carica nulla: mostra solo un avviso.</li></ul><h3 id="la-conferma-alla-prima-apertura" tabindex="-1">La conferma alla prima apertura <a class="header-anchor" href="#la-conferma-alla-prima-apertura" aria-label="Permalink to &quot;La conferma alla prima apertura&quot;">​</a></h3><p>La prima volta che un indirizzo si apre <strong>su questo dispositivo</strong> (per ogni vault) compare «Aprire https://… qui?». Compare anche per chi ha appena creato l&#39;applicazione: un file <code>.webapp</code> può arrivare da un altro dispositivo o, in un vault condiviso, da un&#39;altra persona, e non deve caricare una pagina solo perché esiste. Scegliete <strong>«Apri qui»</strong> se vi fidate dell&#39;indirizzo, oppure <strong>«Apri nel browser»</strong>. La conferma riguarda l&#39;indirizzo registrato nel file: dentro la pagina potete seguire i suoi link. Cambiando l&#39;indirizzo con un sito diverso, la conferma è richiesta di nuovo.</p><h2 id="la-barra-della-scheda" tabindex="-1">La barra della scheda <a class="header-anchor" href="#la-barra-della-scheda" aria-label="Permalink to &quot;La barra della scheda&quot;">​</a></h2><p>Sopra la pagina, nei client con il browser incorporato (macOS, Windows, Linux; dove nel testo compare <code>Mod</code>, è <code>Cmd</code> su macOS e <code>Ctrl</code> sugli altri sistemi):</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Che cosa fa</th></tr></thead><tbody><tr><td>Indietro, Avanti</td><td>La cronologia della pagina (<code>Mod+[</code>, <code>Mod+]</code>).</td></tr><tr><td>Ricarica</td><td>Carica di nuovo la pagina, o la riapre se la vista era stata chiusa (<code>Mod+R</code>).</td></tr><tr><td>Indirizzo</td><td>Dove si trova la pagina adesso, <strong>solo come testo</strong>: non si digita. Per cambiare l&#39;indirizzo dell&#39;applicazione usate «Cambia indirizzo».</td></tr><tr><td>Cambia indirizzo</td><td>Scrive un nuovo indirizzo nel file (anche dalla palette: <em>Cambia l&#39;indirizzo dell&#39;applicazione</em>).</td></tr><tr><td>Apri nel browser</td><td>Apre la pagina in cui siete adesso nel browser di sistema (anche dalla palette: <em>Apri l&#39;applicazione nel browser</em>).</td></tr></tbody></table><p>Sotto la barra compaiono, in un elenco chiudibile, gli avvisi sulla pagina: una navigazione bloccata, una nuova finestra rifiutata o aperta nel browser, un download rifiutato, un permesso negato.</p><p>Se la pagina non si carica compaiono riquadri chiari: errore di caricamento, <strong>certificato del sito non valido</strong> (non c&#39;è modo di proseguire comunque: si può solo aprire l&#39;indirizzo nel browser se ci si fida), pagina che ha smesso di funzionare, troppe applicazioni aperte, vista chiusa. Ognuno ha «Riprova» e «Apri nel browser».</p><h3 id="che-cosa-succede-alla-pagina-quando-cambiate-scheda" tabindex="-1">Che cosa succede alla pagina quando cambiate scheda <a class="header-anchor" href="#che-cosa-succede-alla-pagina-quando-cambiate-scheda" aria-label="Permalink to &quot;Che cosa succede alla pagina quando cambiate scheda&quot;">​</a></h3><ul><li><strong>Cambiare scheda</strong> nasconde la pagina e la conserva: tornando la ritrovate com&#39;era. Una pagina nascosta ha però i <strong>timer rallentati dal motore web</strong>: una chat o un video in una scheda non attiva possono rallentare o fermarsi. È una scelta: le schede in secondo piano non si tengono «vive».</li><li><strong>Chiudere la scheda</strong> chiude la pagina.</li><li><strong>Due pannelli sulla stessa applicazione</strong> sono due pagine separate.</li><li>Alla riapertura dell&#39;app le schede delle applicazioni <strong>non caricano nulla</strong> finché non le mostrate.</li><li>Una pagina sta sempre sopra l&#39;interfaccia: per questo si nasconde da sola quando trascinate una scheda, uno splitter o un file, e quando aprite la palette, un menu, un dialogo o le impostazioni; poi torna.</li><li>Chiudere il vault, bloccare un vault privato (anche per inattività), togliere una condivisione ricevuta o uscire dall&#39;app chiude le pagine. <strong>Lavorare dentro un&#39;applicazione conta come attività</strong> per il blocco automatico dei vault privati.</li><li>Se un amministratore spegne la funzione nel profilo, le pagine aperte si chiudono e le schede passano al riquadro con «Apri nel browser».</li></ul><h2 id="scorciatoie" tabindex="-1">Scorciatoie <a class="header-anchor" href="#scorciatoie" aria-label="Permalink to &quot;Scorciatoie&quot;">​</a></h2><p>Le scorciatoie dell&#39;app (chiudere la scheda, palette, selettore, indietro, avanti, ricarica…) funzionano anche con il fuoco dentro la pagina: eseguono il comando dell&#39;app, non quello della pagina. Fanno eccezione quelle dell&#39;editor di testo (per esempio il grassetto), che restano alla pagina. I comandi dell&#39;applicazione hanno queste scorciatoie predefinite, che potete cambiare in <em>Impostazioni → Scorciatoie</em>:</p><table tabindex="0"><thead><tr><th>Comando</th><th>Scorciatoia</th></tr></thead><tbody><tr><td><em>Applicazione: indietro</em></td><td><code>Mod+[</code></td></tr><tr><td><em>Applicazione: avanti</em></td><td><code>Mod+]</code></td></tr><tr><td><em>Applicazione: ricarica</em></td><td><code>Mod+R</code></td></tr></tbody></table><p><em>Nuova applicazione</em>, <em>Apri applicazione…</em>, <em>Cambia l&#39;indirizzo dell&#39;applicazione</em>, <em>Apri l&#39;applicazione nel browser</em> ed <em>Elimina i dati delle applicazioni</em> non ne hanno. I comandi di navigazione e <em>Elimina i dati</em> ci sono solo dove c&#39;è il browser incorporato.</p><h2 id="che-cosa-puo-fare-una-pagina-e-che-cosa-no" tabindex="-1">Che cosa può fare una pagina, e che cosa no <a class="header-anchor" href="#che-cosa-puo-fare-una-pagina-e-che-cosa-no" aria-label="Permalink to &quot;Che cosa può fare una pagina, e che cosa no&quot;">​</a></h2><p>La pagina gira in una vista <strong>separata</strong> dall&#39;app, come una scheda di un browser. <strong>Non ha alcun collegamento con Clarae notanda</strong>: non può leggere né scrivere le vostre note, non vede il vault, non può usare i comandi o le funzioni dell&#39;app. In particolare:</p><ul><li>Si aprono solo indirizzi <code>http</code> e <code>https</code>; ogni spostamento della pagina (anche un reindirizzamento) è controllato.</li><li><strong>Non può scaricare file</strong> (il download è rifiutato e ve lo dice) né chiedere <strong>camera, microfono, posizione, notifiche</strong> o l&#39;accesso ai vostri file: il permesso è negato.</li><li><strong>Non apre finestre nuove nell&#39;app.</strong> Se chiede una nuova finestra (<code>window.open</code>, un link che si apre altrove), l&#39;indirizzo va al browser di sistema solo se avete appena lavorato nella pagina, mai da una scheda nascosta e al massimo una volta al secondo.</li><li>Un sito con un <strong>certificato non valido</strong> non si apre e non c&#39;è modo di forzarlo.</li><li><strong>Rete locale.</strong> Potete registrare un indirizzo privato (<code>localhost</code>, un NAS, uno strumento self-hosted). Ma una pagina arrivata da un sito pubblico <strong>non può portarvi</strong> su un indirizzo locale: ci sono servizi del vostro computer (compreso l&#39;accesso al cloud) che non devono essere raggiungibili da un sito. La regola riguarda la pagina nel suo insieme, non ciò che incorpora o richiede dietro le quinte; non protegge da un nome che, risolto, punta a un indirizzo locale.</li><li>Gli avvisi <code>alert</code>, <code>confirm</code> e <code>prompt</code> della pagina non compaiono: <code>alert</code> è confermato da solo, gli altri rispondono «no» e nulla. L&#39;audio e il video partono solo dopo un vostro gesto e il pieno schermo di un elemento della pagina è disattivato.</li><li>L&#39;aspetto e il tema dell&#39;app non si applicano alla pagina. La pagina si presenta come Safari su macOS e su Linux (con il nome del motore, WebKitGTK) e come Edge su Windows.</li></ul><h2 id="dati-di-sessione" tabindex="-1">Dati di sessione <a class="header-anchor" href="#dati-di-sessione" aria-label="Permalink to &quot;Dati di sessione&quot;">​</a></h2><p>Cookie, accessi e archivio locale delle pagine restano <strong>su questo dispositivo</strong>: non sono nel vault, non si sincronizzano e non sono visibili ad altri dispositivi. Sono <strong>separati per vault</strong>: lo stesso sito aperto da due vault ha due sessioni diverse. Su macOS i dati stanno nel contenitore di WebKit (non in una cartella del vault). Su Windows e su Linux stanno nella cartella dei dati dell&#39;app, sotto <code>webapps/</code>, <strong>una cartella per vault</strong>, e <strong>restano anche dopo il riavvio</strong> (cookie compresi).</p><ul><li><strong>Su Windows e su Linux</strong> la sessione dura nel tempo, su ogni versione.</li><li><strong>Su macOS 14 o successivo</strong> la sessione dura nel tempo: chiudendo e riaprendo l&#39;app siete ancora connessi. <strong>Su macOS 13</strong> dura finché l&#39;app è aperta, e <strong>l&#39;app non vi avvisa</strong>.</li><li><strong><em>Elimina i dati delle applicazioni</em></strong> (palette) chiude le pagine del vault e cancella cookie, sessioni e cache delle sue applicazioni su questo dispositivo; ogni applicazione chiederà di nuovo la conferma dell&#39;indirizzo. I file <code>.webapp</code> restano. Non tocca gli altri vault né gli altri dispositivi.</li><li>Se una condivisione ricevuta viene rimossa dall&#39;app, i suoi dati di sessione vengono cancellati. Se invece cancellate la cartella di un vault fuori dall&#39;app, l&#39;app non lo sa subito: se ne accorge da sola, <strong>all&#39;avvio e in background</strong>, e cancella i dati di quel vault solo quando è sicura che non esiste più. Cioè quando il vault non è aperto, non è una condivisione ricevuta e non è tra i vault recenti, oppure vi è ma non lo aprite da più di 30 giorni e la sua cartella non esiste più mentre quella che la conteneva c&#39;è e <strong>non è vuota</strong> (una cartella madre vuota è tipica di un punto di mount, per esempio di rclone, sshfs o Cryptomator, non montato: il vault si tiene). Se il vault era l&#39;unica cosa nella sua cartella, i suoi dati restano (qualche megabyte): eliminateli con <em>Elimina i dati</em>. <strong>Un vault solo chiuso, su un disco esterno scollegato o su un disco di rete non montato non perde mai i dati.</strong> Fino ad allora, o se volete cancellarli subito, eseguite <em>Elimina i dati</em> da un vault aperto allo stesso percorso.</li></ul><h2 id="limiti" tabindex="-1">Limiti <a class="header-anchor" href="#limiti" aria-label="Permalink to &quot;Limiti&quot;">​</a></h2><ul><li><strong>L&#39;autenticazione HTTP di base</strong> (la finestra del browser che chiede nome utente e password) <strong>non è supportata</strong>: la richiesta è annullata e la pagina non si carica. Idem per il certificato client, e per NTLM su macOS e su Linux (su Windows NTLM e Kerberos li gestisce il runtime WebView2). Usate un sito con un accesso in una pagina web.</li><li><strong>I login che si aprono in un popup</strong> e comunicano con la pagina che li ha aperti (<code>window.opener</code>) <strong>non funzionano</strong>: i popup non si aprono nell&#39;app, vanno al browser di sistema.</li><li>Il browser incorporato c&#39;è su <strong>macOS, Windows e Linux</strong>. Il workbench web, e un computer senza il runtime richiesto, aprono la pagina nel browser di sistema. <strong>I driver di Windows e di Linux sono stati provati su una finestra vera il 27 novembre 2026</strong>, con esito positivo, seguendo una matrice di prove manuali (<a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/qa/m18-webview-matrice.md" target="_blank" rel="noreferrer"><code>docs/qa/m18-webview-matrice.md</code></a>). Se la vista si comporta male, spegnetela con <code>CLARAE_WEBVIEW=off</code> e segnalate ciò che vedete.</li><li><strong>Su Linux</strong> il selettore di file della pagina è annullato (come su macOS) e, per sicurezza, una pagina pubblica che incorpora un frame verso un indirizzo locale lo vede rifiutato, come un reindirizzamento verso un indirizzo locale dopo una pagina pubblica. <strong>La sandbox di WebKit è obbligatoria:</strong> se per qualche motivo il processo che disegna la pagina non riesce a partire dopo che il controllo iniziale è riuscito, l&#39;app può chiudersi senza altri avvisi; Flatpak e Snap non sono provati. Se aprite un&#39;applicazione mentre eliminate i dati delle applicazioni dello stesso vault, la scheda mostra un errore con «Riprova».</li><li><strong>Su Windows</strong> lavorare dentro la pagina conta, per il blocco automatico dei vault privati, solo per i tasti e il fuoco: chi legge e scorre soltanto è considerato inattivo. Il selettore di file della pagina non si può negare.</li><li><strong>Prove sulla finestra reale:</strong> il posizionamento della pagina con lo zoom dell&#39;app diverso da 100%, lo sfarfallio nel nascondere e mostrare la pagina, il fuoco da tastiera e il trascinamento di una scheda sopra la pagina fanno parte della matrice di prove manuali (<a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/qa/m18-webview-matrice.md" target="_blank" rel="noreferrer"><code>docs/qa/m18-webview-matrice.md</code></a>), eseguita il 27 novembre 2026 con esito positivo (dichiarato, senza esito per riga). Segnalate ciò che vedete.</li><li>Al massimo <strong>32 applicazioni aperte</strong> per vault (64 in tutto). Oltre, la scheda lo dice e propone «Apri nel browser».</li></ul><h2 id="se-qualcosa-non-va" tabindex="-1">Se qualcosa non va <a class="header-anchor" href="#se-qualcosa-non-va" aria-label="Permalink to &quot;Se qualcosa non va&quot;">​</a></h2><ul><li><strong>Non vedo <em>Nuova applicazione</em>.</strong> La funzione è spenta nel vostro profilo di configurazione (o il vault è in sola lettura): chiedete a chi amministra il cloud (<a href="./../admin-guide/profili-quote-audit.html#chiavi-del-profilo">guida per chi amministra</a>).</li><li><strong>La scheda mostra un riquadro invece della pagina.</strong> Senza browser incorporato (workbench web, oppure un computer Windows o Linux senza il runtime richiesto, o con <code>CLARAE_WEBVIEW=off</code>) è normale: usate «Apri nel browser». Dove il browser incorporato c&#39;è potrebbe esserci un errore: leggete il messaggio, poi «Riprova».</li><li><strong>Il file non si apre («Impossibile aprire questa applicazione»).</strong> Il JSON non è valido, l&#39;indirizzo non è <code>http</code> o <code>https</code>, ha credenziali, o il file è stato scritto da una versione più recente: correggete l&#39;indirizzo con «Cambia indirizzo» (o a mano nel file).</li><li><strong>Una pagina chiede un accesso e non funziona.</strong> Vedi <a href="#limiti">Limiti</a>: autenticazione di base e login con popup non sono supportati.</li><li><strong>Troppe applicazioni aperte.</strong> Chiudete qualche scheda e usate «Riprova».</li></ul>',40)])])}const g=a(t,[["render",l]]);export{m as __pageData,g as default};
